/// Every row declared on one base, exactly as declared: an abstract base is
/// not resolved here.
///
/// A scan, because this is a convenience over the table rather than the index
/// path: an extractor that needs the rows per type builds its own map from
/// `SEARCH_PARAMETERS` once at startup rather than calling this per request.
pub fn rows_for_base(base: &str) -> Vec<&'static SearchParamRow> {
    SEARCH_PARAMETERS
        .iter()
        .filter(|row| row.base == base)
        .collect()
}

/// Every row that applies to one concrete resource type: its own first, then
/// each abstract base's, outermost last.
///
/// The base chain is the caller's, because this module holds no type
/// hierarchy and `types.rs` does. Pass the queried type followed by every
/// type above it.
pub fn applicable_to(base_chain: &[&str]) -> Vec<&'static SearchParamRow> {
    base_chain
        .iter()
        .flat_map(|base| rows_for_base(base))
        .collect()
}

/// One row, by parameter id and base.
pub fn row(id: &str, base: &str) -> Option<&'static SearchParamRow> {
    SEARCH_PARAMETERS
        .iter()
        .find(|row| row.id == id && row.base == base)
}
